const main=()=>$('#main');const set=html=>main().innerHTML=html;
async function loadMeta(){let [b,c,s,g]=await Promise.all(['batches','courses','semesters','groups'].map(x=>api(x)));meta={b,c,s,g};return meta}
const batchOpts=()=>meta.b.map(b=>[b.id,b.name]);const semOpts=()=>meta.s.map(s=>[s.id,s.name]);const courseOpts=(courses=meta.c)=>courses.map(c=>[c.id,c.code+' — '+c.name]);const groupOpts=[[0,'All Groups'],[1,'Group 1'],[2,'Group 2']];const trackOpts=[['Honours','Honours'],['Honours with Research','Honours with Research']];
function cards(items){return `<div class="stats">${items.map(([name,value])=>`<div class="stat"><span>${esc(name)}</span><strong>${esc(value??'—')}</strong></div>`).join('')}</div>`}
function profileInfo(p){return `<div class="profile-grid">${Object.entries(p).filter(([k])=>!['id','active','batch_id','created_at'].includes(k)).map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span>${esc(v)}</div>`).join('')}</div>`}
async function dash(){let d=await api('dashboard');if(student()){set(`<section class="panel"><h2>Student Profile</h2>${profileInfo(me.profile)}</section>`+cards([['Classes conducted',d.conducted],['Classes attended',d.present],['Classes absent',d.absent],['Overall attendance',pct(d.present,d.conducted)]])+`<section class="panel"><h2>Subject-wise attendance</h2><div id="student-subjects"></div></section>`);await loadMeta();let rows=await api('reports');$('#student-subjects').innerHTML=subjectTable(rows,meta.c.filter(c=>c.semester===me.profile.semester),Number((await api('settings')).threshold));return}set(cards([['Programme count',1],['Student strength',d.students],['Batch sections',d.batches],['Classes conducted',d.classes],...(admin()?[['Groups',d.groups],['Semesters',8],['Staff',d.staff]]:[]),['Classes today',d.today],['Attendance recorded',d.conducted],['Overall attendance',pct(d.present,d.conducted)]])+`<section class="panel"><h2>Welcome to the Academics Portal</h2><p>Manage attendance and academic records through your permitted assignments.</p><div class="actions"><a href="#attendance-entry">Attendance Entry</a> · <a href="#summary-report">Summary Reports</a> · <a href="#faculty-assignment">Faculty Assignments</a></div></section>`)}
function criteriaHTML(initial={}){return `<div class="grid">${select('batch_id','Batch',batchOpts(),initial.batch_id||'')}${select('semester','Semester',semOpts(),initial.semester||'')}${select('track','Curriculum Track',trackOpts,initial.track||'Honours')}${select('course_id','Course',[],initial.course_id||'')}${select('module','Module No.',[])}${select('class_type','Class Type',[])}${select('group_no','Group',groupOpts,initial.group_no??0)}${input('class_no','Class No.',initial.class_no||1,'number')}${input('date','Attendance Date',initial.date||me.today,'date')}</div>`}
async function wireCriteria(form,initial={}){let get=n=>form.elements[n],refresh=()=>{let sem=+get('semester').value,b=get('batch_id').value,track=get('track').value;get('track').closest('label').hidden=sem!==8;let courses=meta.c.filter(c=>c.semester===sem&&(!c.track||c.track===track)&&(!meta.assign||meta.assign.some(a=>a.batch_id===+b&&a.course_id===c.id)));let prev=get('course_id').value;get('course_id').innerHTML=option('','Select…')+courseOpts(courses).map(o=>option(...o,String(o[0])===String(prev))).join('');types()};function types(){let c=meta.c.find(c=>c.id===+get('course_id').value);let old=get('class_type').value,mod=get('module').value;let types=c?[c.l&&'Theory',c.t&&'Tutorial',c.p&&'Practical',!c.l&&!c.t&&!c.p&&'Project'].filter(Boolean):[];get('class_type').innerHTML=types.length?types.map(t=>option(t,t,t===old)).join(''):option('','Select…');get('module').innerHTML=Array.from({length:c?.modules||5},(_,i)=>option(i+1,'Module '+(i+1),String(i+1)===mod)).join('');get('class_no').min=1;get('class_no').max=c?.max_classes||60;groups()}
function groups(){let old=get('group_no').value,b=+get('batch_id').value,c=+get('course_id').value;let opts=groupOpts.filter(([g])=>(get('class_type').value!=='Practical'||g!==0)&&(!meta.assign||meta.assign.some(a=>a.batch_id===b&&a.course_id===c&&(a.group_no===0||a.group_no===g))));get('group_no').innerHTML=opts.map(o=>option(...o,String(o[0])===old)).join('')||option('','Select…')}
get('batch_id').onchange=()=>{let b=meta.b.find(b=>b.id===+get('batch_id').value);get('semester').value=b?.semester||'';refresh()};get('semester').onchange=refresh;get('track').onchange=refresh;get('course_id').onchange=types;get('class_type').onchange=groups;refresh();if(initial.course_id){get('course_id').value=initial.course_id;types();get('class_type').value=initial.class_type;groups();get('group_no').value=initial.group_no;get('module').value=initial.module;get('class_no').value=initial.class_no;get('date').value=initial.date}}
async function attendance(){await loadMeta();if(!admin())meta.assign=await api('assignments');let id=new URLSearchParams(location.hash.split("?")[1]||"").get('id'),initial={};if(id){let list=await api('attendance');initial=list.find(s=>s.id===+id)||{};if(!initial.id)throw new Error('Session not found or access denied')}
set(`<section class="panel"><form id="criteria">${criteriaHTML(initial)}<div class="actions"><button>Show</button><button type="button" class="secondary" id="reset">Reset</button></div></form></section><div id="roster"></div>`);let f=$('#criteria');await wireCriteria(f,initial);f.elements.date.max=me.today;let rows=[],records=[],original=[],session=null,selected={};function confirmDiscard(){return !dirty||confirm('Discard unsaved attendance selections?')}
async function show(){if(!confirmDiscard())return;selected=formData(f);let result=await api('attendance/roster?'+query(selected));rows=result.students;session=result.session;records=rows.map(s=>{let r=result.records.find(r=>r.student_id===s.id);return {student_id:s.id,present:r?.present??0,remarks:r?.remarks??''}});original=records.map(r=>({...r}));dirty=false;draw()}
function totals(){let p=records.reduce((a,r)=>a+r.present,0);$('#totals').innerHTML=[['Total Students',rows.length],['Present Students',p],['Absent Students',rows.length-p],['Attendance Percentage',pct(p,rows.length)]].map(([k,v])=>`<div>${k}<strong>${v}</strong></div>`).join('');let all=$('#all-check');if(all){all.checked=records.length>0&&p===records.length;all.indeterminate=p>0&&p<records.length}}
function drawRows(){let search=$('#student-search').value.toLowerCase();let rr=rows.map((s,i)=>({s,i})).filter(({s})=>(s.name+' '+s.student_id+' '+s.roll).toLowerCase().includes(search));$('#mark-table').innerHTML=table(['Sl.','Student ID','Roll Number','Student Name','Group','<input id="all-check" type="checkbox" aria-label="Mark all students"> Attendance','Status','Remarks'],rr.map(({s,i})=>[i+1,esc(s.student_id),esc(s.roll),esc(s.name),'Group '+s.group_no,`<input type="checkbox" data-mark="${i}" aria-label="Present for ${esc(s.name)}" ${records[i].present?'checked':''}>`,`<span class="${records[i].present?'present':'absent'}">${records[i].present?'Present':'Absent'}</span>`,`<input data-remark="${i}" aria-label="Remarks for ${esc(s.name)}" value="${esc(records[i].remarks)}">`]));$$('[data-mark]').forEach(c=>c.onchange=()=>{records[+c.dataset.mark].present=+c.checked;dirty=true;drawRows()});$$('[data-remark]').forEach(c=>c.oninput=()=>{records[+c.dataset.remark].remarks=c.value;dirty=true});$('#all-check').onchange=e=>markAll(+e.target.checked);totals()}
function markAll(v){records.forEach(r=>r.present=v);dirty=true;drawRows()}
function draw(){let batch=meta.b.find(b=>b.id===+selected.batch_id),course=meta.c.find(c=>c.id===+selected.course_id);$('#roster').innerHTML=`<section class="panel"><h2>${session?'Existing attendance — modify':'Attendance marking'}</h2><p>${esc(batch?.name)} · Semester ${esc(selected.semester)} · ${esc(course?.name)} · ${esc(selected.class_type)} · ${esc(groupOpts.find(g=>g[0]===+selected.group_no)?.[1])} · Module ${esc(selected.module)} · Class ${esc(selected.class_no)} · ${esc(selected.date)}</p><div class="actions"><button id="mark-present">Mark All Present</button><button id="mark-absent" class="secondary">Mark All Absent</button><input id="student-search" placeholder="Search student" aria-label="Search student"><button id="clear-marks" class="secondary">Reset Attendance Selection</button></div><div id="mark-table"></div><div class="summary" id="totals"></div><div class="actions"><button id="save" ${!rows.length?'disabled':''}>${session?'Update Attendance':'Save Attendance'}</button></div></section>`;drawRows();$('#student-search').oninput=drawRows;bind('#mark-present',()=>markAll(1));bind('#mark-absent',()=>markAll(0));bind('#clear-marks',()=>{if(confirm('Reset all unsaved selections?')){records=original.map(r=>({...r}));dirty=false;drawRows()}});bind('#save',async()=>{let p=records.reduce((a,r)=>a+r.present,0);if(!confirm(`Save ${p} present and ${records.length-p} absent?`))return;let reason=session?prompt('Reason for modification'):'';if(session&&!reason?.trim())return;let b=$('#save');b.disabled=true;try{await api('attendance'+(session?'/'+session.id:''),session?'PUT':'POST',{...selected,records,reason});dirty=false;notify(session?'Attendance updated successfully.':'Attendance saved successfully.');await show()}finally{b.disabled=false}})}
f.onsubmit=action(show);bind('#reset',async()=>{if(!confirmDiscard())return;dirty=false;f.reset();await wireCriteria(f);$('#roster').innerHTML=''});if(id)await show();window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}})}
async function modify(){let rows=await api('attendance');set(`<section class="panel"><div class="actions"><input id="search" placeholder="Search recorded classes" aria-label="Search recorded classes"><a href="#attendance-entry">New Attendance Entry</a></div><div id="list"></div></section>`);function draw(){let q=$('#search').value.toLowerCase();$('#list').innerHTML=table(['Batch','Course','Date','Class','Group','Professor','Actions'],rows.filter(r=>(r.batch_name+' '+r.course_name+' '+r.date).toLowerCase().includes(q)).map(r=>[esc(r.batch_name),esc(r.course_name),esc(r.date),esc(r.class_type)+' '+r.class_no,esc(groupOpts.find(g=>g[0]===r.group_no)[1]),esc(r.professor),`<a href="#attendance-entry?id=${r.id}">Modify</a> <button class="danger small" data-delete="${r.id}">Delete</button>`]));$$('[data-delete]').forEach(b=>b.onclick=action(async()=>{if(!confirm('Delete the entire class session and attendance?'))return;let reason=prompt('Reason for deletion');if(!reason?.trim())return;await api('attendance/'+b.dataset.delete,'DELETE',{reason});rows=await api('attendance');draw();notify('Attendance deleted')}))}$('#search').oninput=draw;draw()}
function status(p,n,t){if(!n)return 'Not Available';let v=p*100/n;return `<span class="${v>=t?'present':v>=65?'warning':'absent'}">${v>=t?'Satisfactory':v>=65?'Warning':'Low Attendance'}</span>`}
function aggregate(rows,keys){let m=new Map();for(let r of rows){let key=keys.map(k=>r[k]).join('|');if(!m.has(key))m.set(key,{...r,n:0,p:0});let a=m.get(key);a.n++;a.p+=r.present}return [...m.values()]}
function subjectTable(rows,courses,t){let groups=aggregate(rows,['course_id']);return table(['Course Code','Course Name','Conducted','Attended','Absent','Attendance','Status'],courses.map(c=>{let r=groups.find(r=>r.course_id===c.id)||{p:0,n:0};return [esc(c.code),esc(c.name),r.n,r.p,r.n-r.p,pct(r.p,r.n),status(r.p,r.n,t)]}))}
function exportCSV(headers,rows,name){let cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';let blob=new Blob([[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const printHeader=title=>`<div class="report-header"><img src="media/bwu-logo.jpg" alt=""><h2>Brainware University — Academic demonstration</h2><p>${esc(title)} · Generated ${esc(me.today)} · Not an official university report.</p></div>`;
async function report(){await loadMeta();let settings=await api('settings'),threshold=+settings.threshold,detail=page==='detailed-report',exam=page==='exam';let students=student()?[]:await api('students');set(`<section class="panel"><form id="filters"><div class="grid">${student()?'':select('batch_id','Batch',batchOpts(),'',false)}${select('semester','Semester',semOpts(),student()?me.profile.semester:'',false)}${select('course_id','Course',courseOpts(),'',false)}${student()?'':select('student_id','Student',students.map(s=>[s.id,s.student_id+' — '+s.name]),'',false)}${student()?'':select('group_no','Group',groupOpts.slice(1),'',false)}${input('from','From date','','date',false)}${input('to','To date','','date',false)}${detail?select('present','Status',[[1,'Present'],[0,'Absent']],'',false):student()?'':select('mode','Report type',[['student','Student-wise'],['course','Course-wise'],['batch','Batch-wise'],['semester','Semester-wise'],['group','Group-wise'],['month','Monthly'],['defaulter','Defaulter list']],'student')}${detail&&!student()?select('mode','Report type',[['detail','Date-wise'],['month','Monthly'],['defaulter','Defaulter list']],'detail'):''}</div><div class="actions"><button>Show Report</button><button type="reset" class="secondary">Reset</button></div></form></section><section class="panel">${printHeader(titles[page])}<div id="report-summary"></div><div class="actions"><button id="csv" class="secondary">Export CSV</button><button id="print" class="secondary">Print / Save PDF</button></div><div id="report-table"></div></section>`);let f=$('#filters'),headers=[],raw=[];f.elements.semester.onchange=()=>{let c=meta.c.filter(c=>!f.elements.semester.value||c.semester===+f.elements.semester.value);f.elements.course_id.innerHTML=option('','All')+courseOpts(c).map(o=>option(...o)).join('')};async function draw(){let q=formData(f),rows=await api('reports?'+query(q)),p=rows.reduce((a,r)=>a+r.present,0);$('#report-summary').innerHTML=`<h2>${esc(titles[page])}</h2><p class="muted">${rows.length} eligible attendance records · ${esc(q.from||'All dates')} to ${esc(q.to||'present')} ${exam?'· Demonstration eligibility threshold: '+threshold+'% (not verified university policy).':''}</p><div class="summary"><div>Conducted<strong>${rows.length}</strong></div><div>Present<strong>${p}</strong></div><div>Absent<strong>${rows.length-p}</strong></div><div>Overall<strong>${pct(p,rows.length)}</strong></div></div>`;let out=[];if(student()&&!detail){let courses=meta.c.filter(c=>(!q.semester||c.semester===+q.semester)&&(!q.course_id||c.id===+q.course_id));let agg=aggregate(rows,['course_id']);headers=['Course Code','Course Name','Conducted','Attended','Absent','Attendance','Status'];raw=courses.map(c=>{let a=agg.find(r=>r.course_id===c.id)||{p:0,n:0};return [c.code,c.name,a.n,a.p,a.n-a.p,pct(a.p,a.n),a.n?(a.p*100/a.n>=threshold?'Satisfactory':a.p*100/a.n>=65?'Warning':'Low Attendance'):'Not Available']});out=raw.map(r=>r.map(esc))}else if(detail&&(!q.mode||q.mode==='detail')){headers=['Date','Student ID','Student','Batch','Course','Class','Professor','Status'];raw=rows.map(r=>[r.date,r.student_code,r.student_name,r.batch_name,r.course_name,r.class_type+' '+r.class_no,r.professor,r.present?'Present':'Absent']);out=raw.map(r=>r.map((v,i)=>i===7?`<span class="${v==='Present'?'present':'absent'}">${v}</span>`:esc(v)))}else{let mode=q.mode||'student';let dims={student:['student_code','student_name','batch_name'],course:['code','course_name'],batch:['batch_name'],semester:['semester'],group:['batch_name','group_no'],month:['month'],defaulter:['student_code','student_name','batch_name']}[mode];rows.forEach(r=>r.month=r.date.slice(0,7));let ag=aggregate(rows,dims);if(mode==='defaulter')ag=ag.filter(r=>100*r.p/r.n<threshold);headers=[...dims.map(k=>k.replaceAll('_',' ')), 'Conducted','Present','Absent','Attendance','Status'];raw=ag.map(r=>[...dims.map(k=>r[k]),r.n,r.p,r.n-r.p,pct(r.p,r.n),r.p*100/r.n>=threshold?'Satisfactory':r.p*100/r.n>=65?'Warning':'Low Attendance']);out=raw.map(r=>r.map(esc))}$('#report-table').innerHTML=table(headers,out)}f.onsubmit=action(draw);f.onreset=()=>setTimeout(()=>{f.elements.semester.onchange();draw().catch(error)},0);bind('#csv',()=>exportCSV(headers,raw,'SAMS-attendance-report'));bind('#print',()=>print());await draw()}
