 'student-management':{api:'students',title:'Student',fields:[['student_id','Student ID'],['name','Student Name'],['roll','Roll Number'],['registration','Registration Number'],['batch_id','Batch','batch'],['group_no','Group','group'],['semester','Semester','semester'],['track','Curriculum Track','track'],['language','Modern Indian Language','language'],['email','Demo Email'],['active','Status','active']],cols:[['student_id','Student ID'],['name','Student Name'],['roll','Roll Number'],['batch_name','Batch'],['group_no','Group'],['semester','Semester'],['active','Active']]},
